402	    /** Combined result of {@link #surveyForward}: the four-map interaction classification plus
403	     *  the stiffest finite neighbor impedance found during that same survey (or {@link Double#NaN}
404	     *  when no neighbor resolved to a finite impedance). */
405	    private record ForwardSurvey(FrustumLod.Interaction interaction, double wallImpedance) {}
406	
407	    /**
408	     * Surveys N/E/D at the same LOD as {@code cellOrigin} in one pass, returning both the
409	     * four-map interaction (host→neighbor interaction permeate, {@link FrustumLod#blocksPermeation},
410	     * not raw impedance stiffness; missing neighbors count as open) and the wall impedance
411	     * ({@code max} of the finite neighbor impedances) needed to resolve a boundary that turned out
412	     * non-reflective. Returns {@code null} when the DDA projection says this exit is a single-axis
413	     * (non-NED) step.
414	     */
415	    private @Nullable ForwardSurvey surveyForward(
416	            BlockPos cellOrigin,
417	            Vec3d cellBase,
418	            int cellSize,
419	            Vec3d hitPos,
420	            Vec3i face,
421	            Vec3d rayDir,
422	            double hostImpedance
423	    ) {
424	        FrustumLod.ForwardMap map = FrustumLod.forwardMap(cellBase, cellSize, hitPos, rayDir, face);
425	        if (map == null) {
426	            return null;
427	        }
428	
429	        Branch nBranch = lodAt(cellOrigin.add(map.nOffset().getX(), map.nOffset().getY(), map.nOffset().getZ()), cellSize);
430	        double nZ = impedanceOf(nBranch);
431	        boolean nBlocks = FrustumLod.blocksPermeation(hostImpedance, nZ, permeationOf(nBranch));
432	
433	        double eZ = Double.NaN;
434	        double dZ = nZ;
435	        boolean eBlocks = false;
436	        boolean dBlocks = nBlocks;
437	        if (map.hasTangent()) {
438	            Branch eBranch = lodAt(cellOrigin.add(map.eOffset().getX(), map.eOffset().getY(), map.eOffset().getZ()), cellSize);
439	            eZ = impedanceOf(eBranch);

440	            eBlocks = FrustumLod.blocksPermeation(hostImpedance, eZ, permeationOf(eBranch));
441	
442	            Branch dBranch = lodAt(cellOrigin.add(map.dOffset().getX(), map.dOffset().getY(), map.dOffset().getZ()), cellSize);
443	            dZ = impedanceOf(dBranch);
444	            dBlocks = FrustumLod.blocksPermeation(hostImpedance, dZ, permeationOf(dBranch));
445	        }
446	
447	        FrustumLod.Interaction interaction = FrustumLod.classify(nBlocks, eBlocks, dBlocks);
448	
449	        double wall = Double.NEGATIVE_INFINITY;
450	        if (Double.isFinite(nZ)) wall = Math.max(wall, nZ);
451	        if (Double.isFinite(eZ)) wall = Math.max(wall, eZ);
452	        if (Double.isFinite(dZ)) wall = Math.max(wall, dZ);
453	        double wallImpedance = wall == Double.NEGATIVE_INFINITY ? Double.NaN : wall;
454	
455	        return new ForwardSurvey(interaction, wallImpedance);
456	    }
