465	    private @Nullable Branch lodAt(BlockPos pos, int lod) {
466	        if (chunk != null) {
467	            ChunkChain c = chunk.access(pos.getX() >> 4, pos.getZ() >> 4);
468	            if (c != null) {
469	                Branch root = c.getBranch(pos.getY() >> 4);
470	                if (root != null) {
471	                    return root.getAtLod(pos, lod);
472	                }
473	            }
474	        }
475	        return tree == null ? null : tree.getAtLod(pos, lod);
476	    }
