478	    private static double impedanceOf(@Nullable Branch b) {
479	        if (b == null) {
480	            return Double.NaN;
481	        }
482	        if (!Double.isNaN(b.avgImpedance)) {
483	            return b.avgImpedance;
484	        }
485	        if (!Double.isNaN(b.mostCommonImpedance)) {
486	            return b.mostCommonImpedance;
487	        }
488	        return b.material != null ? b.material.impedance() : Double.NaN;
489	    }
