491	    private static double polarizedImpedance(Branch branch, Vec3d vector) {
492	        double w = polarBlendWeight(branch, vector);
493	        return Physics.blendImpedance(branch.mostCommonImpedance, branch.leastCommonImpedance, w);
494	    }
495	
496	    private static double polarBlendWeight(Branch branch, Vec3d vector) {
497	        Vec3d pol = branch.polar;
498	        if (pol == null || pol.lengthSquared() < 1e-12) {
499	            return 0.5;
500	        }
501	        double s = !Double.isNaN(branch.blendCoefficient) && branch.blendCoefficient >= 0.75 ? 2.0 : 1.0;
502	        return Physics.polarBlendWeight(Physics.polarAlignment(vector.normalize(), pol.normalize()), s);
503	    }
504	
505	    private static double polarContrast(Branch branch) {
506	        double most = branch.mostCommonImpedance;
507	        double least = branch.leastCommonImpedance;
508	        double denom = Math.max(Math.abs(most), Math.abs(least));
509	        if (denom < 1e-9 || Double.isNaN(denom)) {
510	            return 0.0;
511	        }
512	        return Math.abs(most - least) / denom;
513	    }
