321	     * Four-map classifier. {@code n}/{@code e}/{@code d} are whether the host→neighbor interaction
322	     * blocks (low permeate — see {@link #blocksPermeation}). Head-on (no {@code E}) is
323	     * {@link Interaction#FACE} when {@code N} blocks, else {@link Interaction#GAP}.
324	     */
325	    public static @NotNull Interaction classify(boolean nBlocks, boolean eBlocks, boolean dBlocks) {
326	        if (nBlocks && eBlocks && dBlocks) {
327	            return Interaction.CORNER;
328	        }
329	        if (nBlocks && eBlocks) {
330	            return Interaction.SPLIT;
331	        }
332	        if (nBlocks && dBlocks) {
333	            return Interaction.FACE;
334	        }
335	        if (nBlocks) {
