344	    /**
345	     * Host→neighbor interaction permeate: {@code (1 - R(host, neighbor)) * neighborPermeation}.
346	     * Missing/non-finite neighbor impedance → fully open ({@code 1}). Non-finite neighbor
347	     * permeation defaults to {@code 1} so impedance mismatch alone still drives the result.
348	     */
349	    public static double interactionPermeation(double hostZ, double neighborZ, double neighborPermeation) {
350	        if (!Double.isFinite(neighborZ) || !Double.isFinite(hostZ)) {
351	            return 1.0;
352	        }
353	        double r = Acoustics.reflection(hostZ, neighborZ);
354	        double perm = Double.isFinite(neighborPermeation) ? neighborPermeation : 1.0;
355	        return (1.0 - r) * perm;
356	    }
