194	    /**
195	     * Builds the N/E/D map from the first exit plane and the next same-size DDA face the ray would
196	     * strike after crossing it. The second face is pure arithmetic (virtual neighbor cell of
197	     * {@code cellSize}) — no octree fetch. Returns {@code null} when that projected face shares
198	     * {@code firstPlane}'s axis (ordinary non-NED DDA boundary).
199	     *
200	     * @param cellBase   min corner of H
201	     * @param hitPos     position on the first exit face
202	     * @param firstPlane Cast plane ({@code -sign(ray)} on the crossed axis)
203	     */
204	    public static @Nullable ForwardMap forwardMap(
205	            @NotNull Vec3d cellBase,
206	            int cellSize,
207	            @NotNull Vec3d hitPos,
208	            @NotNull Vec3d rayDir,
209	            @NotNull Vec3i firstPlane
210	    ) {
211	        if (firstPlane.equals(Vec3i.ZERO)) {
212	            return null;
213	        }
214	        int s = Math.max(1, cellSize);
215	        int nAxis = faceAxis(firstPlane);
216	        int nSign = travelSign(firstPlane, rayDir, nAxis);
217	        Vec3i secondPlane = nextDdaPlane(cellBase, s, hitPos, rayDir, nAxis, nSign);
218	        if (secondPlane == null || secondPlane.equals(Vec3i.ZERO)) {
219	            return null;
220	        }
221	        int eAxis = faceAxis(secondPlane);
222	        if (eAxis == nAxis) {
223	            return null;
224	        }
225	        int eSign = travelSign(secondPlane, rayDir, eAxis);
226	        if (eSign == 0) {
227	            return null;
228	        }
229	        Vec3i n = axisUnit(nAxis, nSign * s);
230	        Vec3i e = axisUnit(eAxis, eSign * s);
231	        Vec3i d = new Vec3i(n.getX() + e.getX(), n.getY() + e.getY(), n.getZ() + e.getZ());
232	        return new ForwardMap(n, e, d, nAxis, eAxis);
233	    }
