235	    /**
236	     * Next face plane the ray would exit after entering the same-size neighbor beyond
237	     * {@code firstAxis}/{@code firstTravelSign}. Does not sample the octree — only assumes a
238	     * {@code cellSize} cube abutting H. Plane uses Cast's {@code -sign(ray)} convention.
239	     */
240	    public static @Nullable Vec3i nextDdaPlane(
241	            @NotNull Vec3d cellBase,
242	            int cellSize,
243	            @NotNull Vec3d hitPos,
244	            @NotNull Vec3d rayDir,
245	            int firstAxis,
246	            int firstTravelSign
247	    ) {
248	        int s = Math.max(1, cellSize);
249	        if (firstTravelSign == 0) {
250	            return null;
251	        }
252	        double nextX = cellBase.x + (firstAxis == 0 ? firstTravelSign * s : 0);
253	        double nextY = cellBase.y + (firstAxis == 1 ? firstTravelSign * s : 0);
254	        double nextZ = cellBase.z + (firstAxis == 2 ? firstTravelSign * s : 0);
255	        return ddaExitPlane(nextX, nextY, nextZ, s, hitPos, rayDir);
