258	    /**
259	     * Argmin axis exit from an AABB, matching {@code Cast.getStepPair}'s bound/tie rules. Plane
260	     * components are {@code -sign(dir)} on the winning axis.
261	     */
262	    static @Nullable Vec3i ddaExitPlane(
263	            double baseX, double baseY, double baseZ,
264	            int size,
265	            @NotNull Vec3d position,
266	            @NotNull Vec3d vector
267	    ) {
268	        double xstep = boundAxis(baseX, position.x, size, vector.x);
269	        double ystep = boundAxis(baseY, position.y, size, vector.y);
270	        double zstep = boundAxis(baseZ, position.z, size, vector.z);
271	
272	        boolean yWins = ystep < xstep;
273	        double coefficient = yWins ? ystep : xstep;
274	        int axis = yWins ? 1 : 0;
275	
276	        boolean zWins = zstep < coefficient;
277	        coefficient = zWins ? zstep : coefficient;
278	        axis = zWins ? 2 : axis;
279	
280	        if (!(coefficient > 0) || !Double.isFinite(coefficient)) {
281	            return null;
282	        }
283	        double dir = axis == 0 ? vector.x : axis == 1 ? vector.y : vector.z;
284	        int planeSign = dir > 0 ? -1 : dir < 0 ? 1 : 0;
285	        if (planeSign == 0) {
286	            return null;
287	        }
288	        return axisUnit(axis, planeSign);
