392	    private static void subdivide(WorldChunk chunk, Branch node) {
393	        int half = node.size >> 1;
394	        Branch[] children = new Branch[blockSequence.length];
395	        for (int i = 0; i < blockSequence.length; i++) {
396	            BlockPos offset = blockSequence[i];
397	            BlockPos origin = node.start.add(offset.multiply(half));
398	            Branch child = new Branch(origin, half);
399	            if (half == 1) {
400	                BlockState state = chunk.getBlockState(origin);
401	                child.material = MaterialRegistry.material(state);
402	                bakeLeafDescriptor(child);
403	            } else {
404	                BlockState corner = chunk.getBlockState(origin);
405	                if (regionHomogeneous(chunk, origin, half, corner)) {
406	                    child.material = MaterialRegistry.material(corner);
407	                    bakeLeafDescriptor(child);
408	                } else {
409	                    growOctree(chunk, child);
410	                }
411	            }
412	            children[i] = child;
413	            node.put(i, child);
414	        }
415	        bakeAggregateDescriptor(node, children);
416	    }
