171		/**
172		 * Groups live bounce segments by env-eval cast {@code rayIndex} (the 64 polylines), first-seen
173		 * order. Interleaved rays stay separate; connectivity is not used. Markers ({@code rayIndex < 0}
174		 * or zero-length) are skipped.
175		 */
176		public static List<List<LineSegment>> groupByRayIndex(List<LineSegment> snapshot) {
177			LinkedHashMap<Integer, List<LineSegment>> byRay = new LinkedHashMap<>();
178			double epsSq = CONNECT_EPS * CONNECT_EPS;
179			for (LineSegment segment : snapshot) {
180				if (segment.rayIndex() < 0) {
181					continue;
182				}
183				if (segment.start().squaredDistanceTo(segment.end()) <= epsSq) {
184					continue;
185				}
186				byRay.computeIfAbsent(segment.rayIndex(), ignored -> new ArrayList<>()).add(segment);
187			}
188			List<List<LineSegment>> rays = new ArrayList<>(byRay.size());
189			for (Map.Entry<Integer, List<LineSegment>> entry : byRay.entrySet()) {
190				rays.add(List.copyOf(entry.getValue()));
191			}
192			return rays;
193		}
