195		/**
196		 * @deprecated Prefer {@link #groupByRayIndex}; connectivity splits interleaved casts.
197		 */
198		public static List<List<LineSegment>> groupConnectedRays(List<LineSegment> snapshot) {
199			List<List<LineSegment>> rays = new ArrayList<>();
200			List<LineSegment> current = new ArrayList<>();
201			LineSegment lastReal = null;
202			double epsSq = CONNECT_EPS * CONNECT_EPS;
203			for (LineSegment segment : snapshot) {
204				if (segment.start().squaredDistanceTo(segment.end()) <= epsSq) {
205					continue;
206				}
207				if (lastReal != null && lastReal.end().squaredDistanceTo(segment.start()) > epsSq) {
208					if (!current.isEmpty()) {
209						rays.add(List.copyOf(current));
210						current = new ArrayList<>();
211					}
212				}
213				current.add(segment);
214				lastReal = segment;
215			}
216			if (!current.isEmpty()) {
217				rays.add(List.copyOf(current));
218			}
219			return rays;
220		}
