222		public void addTerminatorCross(Vec3d center) {
223			if (!pConfig.dRays) {
224				return;
225			}
226			// Marker-only entry: shares the segment ring buffer so crosses expire with their rays.
227			addSegment(center, center, TERMINATED_COLOR, BASE_LINE_WIDTH, true);
228		}
