230		private void renderTerminatorCrosses(Matrix4f positionMatrix, Matrix4f projectionMatrix, Vec3d cameraPos) {
231			List<LineSegment> snapshot = segmentSnapshot();
232			boolean hasMarkers = false;
233			for (LineSegment segment : snapshot) {
234				if (segment.terminator()) {
235					hasMarkers = true;
236					break;
237				}
238			}
239			if (!hasMarkers) {
240				return;
241			}
242	
243			terminatorBuffer.markDirty();
244			terminatorBuffer.rebuild(builder -> {
245				for (LineSegment segment : snapshot) {
246					if (!segment.terminator()) {
247						continue;
248					}
249					double x = segment.end().x;
250					double y = segment.end().y;
251					double z = segment.end().z;
252					double s = MARKER_HALF_EXTENT;
253					GpuLineBuffer.line(builder, x - s, y, z, x + s, y, z, TERMINATED_COLOR);
254					GpuLineBuffer.line(builder, x, y - s, z, x, y + s, z, TERMINATED_COLOR);
255					GpuLineBuffer.line(builder, x, y, z - s, x, y, z + s, TERMINATED_COLOR);
256				}
257			});
258			terminatorBuffer.draw(positionMatrix, projectionMatrix, cameraPos);
259		}
260	
261		static float lineWidthFor(double power, int bounceIndex) {
262			float scaled = (float) (BASE_LINE_WIDTH * power / REFERENCE_POWER);
263			return Math.max(1.0F, scaled - bounceIndex);
264		}
265	}
