586			Vec3d position = sourcePos;
587			double traveled = 0.0;
588			double blocked = 0.0;
589			int legs = 0;
590			int guard = 512;
591	
592			while (power > 1.0 && traveled < totalDistance - 1e-4 && guard-- > 0) {
593				cast.raycast(position, direction, power);
594				if (cast.transmitted == null || cast.transmitted.vector() == null) {
