414		private static void recordCastCell(
415				Branch root,
416				Vec3d start,
417				Vec3d end,
418				Vec3d direction,
419				int branchSize,
420				LinkedHashMap<Long, Occupancy> byKey,
421				@Nullable List<Vec3d> markers,
422				@Nullable Integer color,
423				@Nullable Integer setId
424		) {
425			int size = Math.max(1, branchSize);
426			Vec3d dir = direction.lengthSquared() > 1e-12 ? direction : new Vec3d(1, 0, 0);
427			Vec3d probe = Cast.normalize(start, dir);
428			BlockPos query = BlockPos.ofFloored(probe);
429			BlockPos cellOrigin = FrustumLod.alignOrigin(query, root.start, size);
430			Branch lod = root.getAtLod(query, size);
431			Branch finest = root.get(query);
432			boolean virtual = finest.size > size;
433			Box box = boxOf(cellOrigin, size);
434			Occupancy occ = upsertOccupancy(
435					byKey, cellOrigin, size, virtual, virtual ? null : "leaf", lod.polar(), color, setId, dir);
436			if (markers != null && occ.contact == null) {
