452			Vec3d dir = incident.lengthSquared() > 1e-12 ? incident.normalize() : incident;
453			int step = Math.max(1, castStepSize);
454			Vec3d hostProbe = Cast.normalize(hit, dir.multiply(-1.0));
455			BlockPos hostQuery = BlockPos.ofFloored(hostProbe);
456			BlockPos hostOrigin = FrustumLod.alignOrigin(hostQuery, root.start, step);
457	
458			Vec3d cellBase = new Vec3d(hostOrigin.getX(), hostOrigin.getY(), hostOrigin.getZ());
459			Vec3i firstPlane = FrustumLod.castPlaneAtHit(hit, cellBase, step, dir);
460			Vec3i exitFace = FrustumLod.forwardFace(firstPlane, dir);
461	
462			// Recolor H only if the cast already recorded it — do not invent a host cube here.
