316		static CastPathOverlay collectCastVisitedOverlay(
317				List<RayLineLayer.LineSegment> path,
318				Function<Vec3d, Branch> rootFor
319		) {
320			LinkedHashMap<Long, Occupancy> byKey = new LinkedHashMap<>();
321			List<Vec3d> markers = new ArrayList<>();
322			Vec3d prevDir = null;
323			Vec3d prevEnd = null;
324			int prevBranchSize = 1;
325			int setId = 0;
326			for (RayLineLayer.LineSegment segment : path) {
327				Vec3d delta = segment.end().subtract(segment.start());
328				double length = delta.length();
329				if (length < 1e-4) {
330					continue;
331				}
332				Vec3d dir = delta.multiply(1.0 / length);
333				int stepSize = Math.max(1, segment.branchSize());
334				if (prevDir != null && prevEnd != null && prevBranchSize > 1 && isDirectionChange(prevDir, dir)) {
335					Branch bounceRoot = rootFor.apply(prevEnd);
336					if (bounceRoot != null) {
337						int id = setId++;
338						recordBounceOff(bounceRoot, prevEnd, prevDir, prevBranchSize, byKey,
339								OctantColor.forSet(id), id);
340					}
341				}
342				Branch root = rootFor.apply(segment.start());
343				if (root != null) {
344					recordCastCell(root, segment.start(), segment.end(), dir, stepSize, byKey, markers, null, null);
345				}
346				prevDir = dir;
347				prevEnd = segment.end();
348				prevBranchSize = stepSize;
349			}
350			return new CastPathOverlay(occupanciesToViews(byKey), List.copyOf(markers));
351		}
