201		public static List<List<LineSegment>> groupByRayIndex(List<LineSegment> snapshot) {
202			LinkedHashMap<Integer, List<LineSegment>> byRay = new LinkedHashMap<>();
203			double epsSq = CONNECT_EPS * CONNECT_EPS;
204			for (LineSegment segment : snapshot) {
